<?php
namespace App\Filament\Resources;
use App\Models\Invoice; use Filament\Forms; use Filament\Forms\Form; use Filament\Resources\Resource; use Filament\Tables; use Filament\Tables\Table;
class InvoiceResource extends Resource { protected static ?string $model=Invoice::class; protected static ?string $navigationGroup='Finance'; protected static ?string $navigationIcon='heroicon-o-receipt-percent'; public static function canViewAny():bool{return auth()->user()?->can('financials.manage')??false;} public static function form(Form $form):Form{return $form->schema([Forms\Components\Select::make('service_request_id')->relationship('request','reference')->required(),Forms\Components\Select::make('quotation_id')->relationship('quotation','number'),Forms\Components\Repeater::make('items')->relationship()->schema([Forms\Components\TextInput::make('description')->required(),Forms\Components\TextInput::make('quantity')->numeric()->minValue(1)->default(1)->required(),Forms\Components\TextInput::make('unit_price')->numeric()->minValue(0)->required(),Forms\Components\TextInput::make('discount')->numeric()->minValue(0)->default(0)])->columns(4)->minItems(1),Forms\Components\TextInput::make('discount')->numeric()->minValue(0)->default(0),Forms\Components\TextInput::make('tax')->numeric()->minValue(0)->default(0),Forms\Components\DatePicker::make('issued_at'),Forms\Components\DatePicker::make('due_at'),Forms\Components\Select::make('status')->options(['draft'=>'Draft','issued'=>'Issued','partially_paid'=>'Partially paid','paid'=>'Paid','overdue'=>'Overdue','void'=>'Void','refunded'=>'Refunded'])->default('draft'),Forms\Components\Textarea::make('notes'),Forms\Components\Textarea::make('terms')]);} public static function table(Table $table):Table{return $table->defaultSort('created_at','desc')->columns([Tables\Columns\TextColumn::make('number')->searchable(),Tables\Columns\TextColumn::make('request.reference')->searchable(),Tables\Columns\TextColumn::make('total')->money('AED'),Tables\Columns\TextColumn::make('amount_paid')->money('AED'),Tables\Columns\TextColumn::make('balance_due')->money('AED'),Tables\Columns\BadgeColumn::make('status')->searchable()])->filters([Tab